macro_rules! impl_is_retryable {
    ($($response:ident),* $(,)?) => {
        $(impl retry_please::IsRetryable for $crate::types::$response {
            fn is_retryable(&self) -> bool {
                self.status_code == 429.0 || (self.status_code == 400.0 && self.message == "Doc is not yet up to date.")
            }
        })*
    };
}

